do $$ begin create type public.academic_year_status as enum ('planning','current','closed'); exception when duplicate_object then null; end $$;
create table public.academic_years (id uuid primary key default gen_random_uuid(), label text not null unique check(char_length(label) between 4 and 30), start_date date not null, end_date date not null, status public.academic_year_status not null default 'planning', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id) on delete set null, updated_by uuid references auth.users(id) on delete set null, check(end_date > start_date));
create unique index academic_years_one_current_idx on public.academic_years(status) where status='current';
create table public.school_classes (id uuid primary key default gen_random_uuid(), name text not null unique check(char_length(name) between 1 and 40), display_order integer not null unique check(display_order between 0 and 100), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id) on delete set null, updated_by uuid references auth.users(id) on delete set null);
insert into public.school_classes(name,display_order) values ('Nursery',1),('LKG',2),('UKG',3),('Class 1',4),('Class 2',5),('Class 3',6),('Class 4',7),('Class 5',8),('Class 6',9),('Class 7',10),('Class 8',11),('Class 9',12),('Class 10',13) on conflict(name) do nothing;
create table public.academic_sections (id uuid primary key default gen_random_uuid(), academic_year_id uuid not null references public.academic_years(id) on delete restrict, class_id uuid not null references public.school_classes(id) on delete restrict, name text not null check(char_length(name) between 1 and 20), active boolean not null default true, class_teacher_id uuid references public.staff_members(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id) on delete set null, updated_by uuid references auth.users(id) on delete set null, unique(academic_year_id,class_id,name));
create table public.subjects (id uuid primary key default gen_random_uuid(), name text not null unique check(char_length(name) between 1 and 100), code text unique check(code is null or char_length(code) between 1 and 20), display_order integer not null default 0 check(display_order between 0 and 10000), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id) on delete set null, updated_by uuid references auth.users(id) on delete set null);
create table public.section_subject_assignments (id uuid primary key default gen_random_uuid(), academic_section_id uuid not null references public.academic_sections(id) on delete restrict, subject_id uuid not null references public.subjects(id) on delete restrict, teacher_id uuid references public.staff_members(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id) on delete set null, updated_by uuid references auth.users(id) on delete set null, unique(academic_section_id,subject_id));
create index academic_sections_year_class_idx on public.academic_sections(academic_year_id,class_id,active); create index section_subject_assignments_section_idx on public.section_subject_assignments(academic_section_id); create index section_subject_assignments_teacher_idx on public.section_subject_assignments(teacher_id) where teacher_id is not null;
create or replace function public.set_academic_audit_fields() returns trigger language plpgsql security invoker set search_path=public as $$ begin if tg_op='INSERT' then new.created_by=auth.uid(); end if; new.updated_by=auth.uid(); new.updated_at=now(); return new; end; $$;
create or replace function public.assert_active_teaching_staff() returns trigger language plpgsql security invoker set search_path=public as $$ declare teacher uuid; begin teacher:=case when tg_table_name='academic_sections' then new.class_teacher_id else new.teacher_id end; if teacher is not null and not exists(select 1 from public.staff_members where id=teacher and staff_type='teacher' and employment_status='active') then raise exception 'Teacher assignment requires an active teaching staff member' using errcode='23514'; end if; return new; end; $$;
create trigger academic_years_audit before insert or update on public.academic_years for each row execute function public.set_academic_audit_fields(); create trigger school_classes_audit before insert or update on public.school_classes for each row execute function public.set_academic_audit_fields(); create trigger academic_sections_audit before insert or update on public.academic_sections for each row execute function public.set_academic_audit_fields(); create trigger subjects_audit before insert or update on public.subjects for each row execute function public.set_academic_audit_fields(); create trigger section_subject_assignments_audit before insert or update on public.section_subject_assignments for each row execute function public.set_academic_audit_fields(); create trigger academic_sections_teacher_check before insert or update on public.academic_sections for each row execute function public.assert_active_teaching_staff(); create trigger assignments_teacher_check before insert or update on public.section_subject_assignments for each row execute function public.assert_active_teaching_staff();
alter table public.academic_years enable row level security; alter table public.school_classes enable row level security; alter table public.academic_sections enable row level security; alter table public.subjects enable row level security; alter table public.section_subject_assignments enable row level security;
revoke all on public.academic_years,public.school_classes,public.academic_sections,public.subjects,public.section_subject_assignments from anon,authenticated; grant select,insert,update on public.academic_years,public.school_classes,public.academic_sections,public.subjects,public.section_subject_assignments to authenticated;
create policy "Admins manage academic years" on public.academic_years for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin()); create policy "Admins manage school classes" on public.school_classes for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin()); create policy "Admins manage academic sections" on public.academic_sections for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin()); create policy "Admins manage subjects" on public.subjects for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin()); create policy "Admins manage subject assignments" on public.section_subject_assignments for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin());
